const test = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const { upload, checkSize, MAX_BYTES } = require('../upload');

// Start a throwaway local server that mimics the upload endpoint, so the test
// does not depend on an external upload server (none exists in CI).
function startStubServer() {
  const server = http.createServer((req, res) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      if (req.method !== 'POST' || !req.url.startsWith('/upload')) {
        res.writeHead(404).end();
        return;
      }
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ id: 'abc123' }));
    });
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      resolve({ url: `http://127.0.0.1:${port}/upload`, close: () => new Promise((r) => server.close(r)) });
    });
  });
}

test('refuses files over 5 MB', () => {
  assert.throws(() => checkSize(Buffer.alloc(MAX_BYTES + 1)), /too large/);
});

test('uploads a small file and returns its id', async () => {
  const stub = await startStubServer();
  try {
    const id = await upload('a.txt', Buffer.from('hello'), stub.url);
    assert.match(id, /^[a-z0-9]+$/);
  } finally {
    await stub.close();
  }
});

